import { Component, OnInit, HostListener, Injectable } from '@angular/core';

@Injectable()
export class WindowSizeService {
  width = window.innerWidth;
  height = window.innerHeight;

  constructor() {}

  @HostListener('window:resize')
  onResize() {
    this.width = window.innerWidth;
    this.height = window.innerHeight;
  }
}

@Component({
  selector: 'app-window-size',
  template: '<p>Width: {{ width }}, Height: {{ height }}</p>'
})
export class WindowSizeComponent implements OnInit {
  width = 0;
  height = 0;

  constructor(private windowSizeService: WindowSizeService) {}

  ngOnInit() {
    this.width = this.windowSizeService.width;
    this.height = this.windowSizeService.height;
  }
}
